#include <iostream>
using namespace std;

int main() {
    int h, n;
    cin >> h >> n;
    h -= 1;
    n -= 1;
    int low = 0;
    int high = 2 << h;
    bool flag = true;
    int total = 0;
    int step = 0;
    while (high - low > 1) {
        int mid_point = (low + high) / 2;
        if (flag == (n < mid_point)) {
            total += 1;
        } else {
            total += 1 << (h - step + 1);
        }
        if (n < mid_point) {
            high = mid_point;
            flag = false;
        } else {
            low = mid_point;
            flag = true;
        }
        step++;
    }
    cout << total << endl;
    return 0;
}
